import {Component,OnInit,OnDestroy} from '@angular/core';import {CommonModule} from '@angular/common';import {FormsModule} from '@angular/forms';import {RouterModule} from '@angular/router';import {HttpClient} from '@angular/common/http';import {firstValueFrom,Subscription} from 'rxjs';import {ReservationAuthService} from '../services/reservation-auth.service';import {LanguageService} from '../services/language.service';import {PlatformLayoutComponent} from '../layout/platform-layout/platform-layout.component';
@Component({standalone:true,imports:[CommonModule,FormsModule,RouterModule,PlatformLayoutComponent],templateUrl:'./document-review.component.html',styleUrls:['./asset-documents.component.scss']})
export class DocumentReviewComponent implements OnInit,OnDestroy{data:any;error='';busy=false;filter='all';query='';private sub?:Subscription;private sequence=0;constructor(private http:HttpClient,private auth:ReservationAuthService,public language:LanguageService){}ngOnInit(){this.sub=this.language.language$.subscribe(()=>void this.refresh());}ngOnDestroy(){this.sequence++;this.sub?.unsubscribe();}t(k:string){return this.data?.labels?.[k]||({adminTitle:'Validation des justificatifs',error:'Impossible de charger les dossiers.'} as any)[k]||k;}async refresh(){const n=++this.sequence;this.busy=true;this.error='';try{const uid=(await this.auth.user()).uid,data=await firstValueFrom(this.http.get<any>('/api/platform/admin/documents',{headers:await this.auth.headers(),params:{language:this.language.currentLanguage}}));if(n!==this.sequence||uid!==(await this.auth.user()).uid)return;this.data=data;}catch{if(n===this.sequence){this.error=this.t('error');this.data=null;}}finally{if(n===this.sequence)this.busy=false;}}get rows(){const q=this.query.trim().toLowerCase();return (this.data?.rows||[]).filter((r:any)=>(this.filter==='all'||r.status===this.filter)&&(!q||(r.name+' '+r.ownerName).toLowerCase().includes(q))).sort((a:any,b:any)=>Number(b.status==='pendingReview')-Number(a.status==='pendingReview'));}}
